class InsufficientFunds(Exception):
    """Raised when attempting to withdraw more than the available balance."""
    pass


class BankAccount:
    def __init__(self, owner: str, balance: float = 0):
        if balance < 0:
            raise ValueError("Starting balance cannot be negative")
        self.owner = owner
        self._balance = float(balance)
        self._history = []

    @property
    def balance(self) -> float:
        """Current account balance (read‑only)."""
        return self._balance

    @property
    def history(self):
        """List of successful transactions as tuples: ('deposit'/'withdraw', amount)."""
        return list(self._history)

    def deposit(self, amount: float):
        if amount <= 0:
            raise ValueError("Deposit amount must be positive")
        self._balance += amount
        self._history.append(("deposit", amount))

    def withdraw(self, amount: float):
        if amount <= 0:
            raise ValueError("Withdrawal amount must be positive")
        if amount > self._balance:
            raise InsufficientFunds("Insufficient funds for withdrawal")
        self._balance -= amount
        self._history.append(("withdraw", amount))
